    /// <summary>
    /// 枠線および不透明な黒い領域を持たない透明ウィンドウを生成します。
    /// このウィンドウはほかのウィンドウと同様に順番に整列します。
    /// </summary>
    /// <param name="size"></param>
    /// <param name="parent"></param>
    /// <param name="localPos"></param>
    /// <param name="closeButtonPos"></param>
    /// <param name="withBlackScreen"></param>
    /// <returns></returns>
    static public MetaScreen GenerateBlankWindow(VVector2 size, Transform? parent, VVector3 localPos, VVector2 closeButtonPos, bool withBlackScreen)
    {
        var screen = GenerateScreen(size, parent, localPos, true, withBlackScreen, true);
        var obj = screen.transform.parent.gameObject;
        var button = InstantiateCloseButton(screen, closeButtonPos.AsVector3(0f));
        NebulaManager.Instance.RegisterUI(obj, button);
        return screen;
    }

    static public MetaScreen GenerateWindow(VVector2 size, Transform? parent, VVector3 localPos, bool withBlackScreen, bool closeOnClickOutside, bool withMask, bool withBackground)
        => GenerateWindow(size, parent, localPos, withBlackScreen, closeOnClickOutside, withMask, withBackground ? BackgroundSetting.Old : BackgroundSetting.Off);
    static public MetaScreen GenerateWindow(VVector2 size, Transform? parent, VVector3 localPos, bool withBlackScreen, bool closeOnClickOutside, bool withMask = false, BackgroundSetting background = BackgroundSetting.Old, bool withCloseButton = true)
    {
        var screen = GenerateScreen(size, parent, localPos, background, withBlackScreen, true);

        var obj = screen.transform.parent.gameObject;

        if (withCloseButton)
        {
            if (background == BackgroundSetting.Modern)
            {
                var collider = UnityHelper.CreateObject<BoxCollider2D>("CloseButton", obj.transform, new Vector3(-size.x / 2f - 0.3f, size.y / 2f + 0.2f, -1f));
                collider.transform.localScale = new(0.57f, 0.57f, 1f);
                collider.isTrigger = true;
                collider.gameObject.layer = LayerExpansion.GetUILayer();
                collider.size = new(0.85f, 0.85f);
                SpriteRenderer? renderer = null;
                renderer = collider.gameObject.AddComponent<SpriteRenderer>();
                renderer.sprite = closeButtonSprite.GetSprite(0);
                var button = collider.gameObject.SetUpButton(true);
                button.OnClick.AddListener(() => GameObject.Destroy(obj));
                button.OnMouseOver.AddListener(() => renderer.sprite = closeButtonSprite.GetSprite(1));
                button.OnMouseOut.AddListener(() => renderer.sprite = closeButtonSprite.GetSprite(0));
                NebulaManager.Instance.RegisterUI(obj, button);
            }
            else
            {
                var button = InstantiateCloseButton(screen, new Vector3(-size.x / 2f - 0.6f, size.y / 2f + 0.25f, 0f));
                NebulaManager.Instance.RegisterUI(obj, button);
            }
        }
        else
        {
            NebulaManager.Instance.RegisterUI(obj, null);
        }


        if (closeOnClickOutside)
        {
            obj.transform.FindChild("ClickGuard").GetComponent<PassiveButton>().OnClick.AddListener(() => GameObject.Destroy(obj));
            var myCollider = UnityHelper.CreateObject<BoxCollider2D>("MyScreenCollider", obj.transform, new Vector3(0f, 0f, 0.1f));
            myCollider.isTrigger = true;
            myCollider.size = size;
            myCollider.gameObject.SetUpButton();
        }

        if (withMask)
        {
            var group = UnityHelper.CreateObject<SortingGroup>("Group", obj.transform, Vector3.zero);
            var mask = UnityHelper.CreateObject<SpriteMask>("Mask", group.transform, Vector3.zero);
            mask.sprite = VanillaAsset.FullScreenSprite;
            mask.transform.localScale = size.AsUnityVector3(0f);

            obj.transform.FindChild("Screen").SetParent(group.transform);
        }

        return screen;
    }

    /// <summary>
    /// 
    /// </summary>
    /// <param name="widgetGenerator"></param>
    /// <param name="index"></param>
    /// <param name="range">minを含み、maxを含まないページ範囲</param>
    /// <param name="size"></param>
    /// <param name="parent"></param>
    /// <param name="localPos"></param>
    /// <param name="withBlackScreen"></param>
    /// <param name="closeOnClickOutside"></param>
    /// <param name="withMask"></param>
    /// <param name="withCloseButton"></param>
    /// <returns></returns>
    static public MetaScreen GenerateWindow(Func<int, Virial.Media.GUIWidget> widgetGenerator, int index, (int min, int max) range, Vector2 size, Transform? parent, Vector3 localPos, bool withBlackScreen, bool closeOnClickOutside, bool withMask = false, bool withCloseButton = true)
    {
        var window = GenerateWindow(size, parent, localPos, withBlackScreen, closeOnClickOutside, withMask, BackgroundSetting.Modern, withCloseButton);

        SetUpNavButton(window, increment =>
        {
            if (increment)
            {
                index++;
                if (index >= range.max) index = range.min;
            }
            else
            {
                index--;
                if (index < range.min) index = range.max - 1;
            }
            window.SetWidget(widgetGenerator.Invoke(index), out _);
        });

        window.SetWidget(widgetGenerator.Invoke(index), out _);
        return window;
    }

    static public void SetUpNavButton(MetaScreen screen, Action<bool> navFunc)
    {
        var obj = screen.transform.parent.gameObject;

        PassiveButton GenerateButton(float x, int img)
        {
            var collider = UnityHelper.CreateObject<BoxCollider2D>("NavButton", obj.transform, new Vector3(screen.Border.x / 2f + 0.3f - x, screen.Border.y / 2f + 0.25f, -1f));
            collider.transform.localScale = new(0.57f, 0.57f, 1f);
            collider.isTrigger = true;
            collider.gameObject.layer = LayerExpansion.GetUILayer();
            collider.size = new(0.65f, 0.65f);
            SpriteRenderer? renderer = null;
            renderer = collider.gameObject.AddComponent<SpriteRenderer>();
            renderer.sprite = navButtonSprite.GetSprite(img);
            var button = collider.gameObject.SetUpButton(true);
            button.OnMouseOver.AddListener(() => renderer.sprite = navButtonSprite.GetSprite(img + 1));
            button.OnMouseOut.AddListener(() => renderer.sprite = navButtonSprite.GetSprite(img));
            return button;
        }

        GenerateButton(0.7f, 0).OnClick.AddListener(() => {
            navFunc.Invoke(false);
        });
        GenerateButton(0.3f, 2).OnClick.AddListener(() =>
        {
            navFunc.Invoke(true);
        });
    }

